"""Finite DirectSound root exports and COM methods, with explicit buffer stops."""
import importlib.util,pathlib
R=pathlib.Path(__file__).resolve().parents[1]
METHODS=[('QueryInterface','query',3),('AddRef','addref',1),('Release','release',1),('CreateSoundBuffer','create_buffer',4),('GetCaps','caps',2),('DuplicateSoundBuffer',None,3),('SetCooperativeLevel','cooperative',3),('Compact','compact',1),('GetSpeakerConfig','get_speaker',2),('SetSpeakerConfig','set_speaker',2),('Initialize','initialize',2)]
BUFFER_METHODS=[('QueryInterface','query',3),('AddRef','addref',1),('Release','release',1),('GetCaps','caps',2),('GetCurrentPosition','position',3),('GetFormat','format',4),('GetVolume','volume',2),('GetPan','pan',2),('GetFrequency','frequency',2),('GetStatus','status',2),('Initialize',None,3),('Lock','lock',8),('Play','play',4),('SetCurrentPosition','set_position',2),('SetFormat','set_format',2),('SetVolume','set_volume',2),('SetPan','set_pan',2),('SetFrequency','set_frequency',2),('Stop','stop',1),('Unlock','unlock',5),('Restore',None,1)]
LISTENER_METHODS=[('QueryInterface','tribes_dsb_query',3),('AddRef','tribes_dsb_addref',1),('Release','tribes_dsb_release',1)]+[(name,'tribes_dsl_'+helper,n) for name,helper,n in [('GetAllParameters','get_all',2),('GetDistanceFactor','get_distance',2),('GetDopplerFactor','get_doppler',2),('GetOrientation','get_orientation',3),('GetPosition','get_position',2),('GetRolloffFactor','get_rolloff',2),('GetVelocity','get_velocity',2),('SetAllParameters','set_all',3),('SetDistanceFactor','set_distance',3),('SetDopplerFactor','set_doppler',3),('SetOrientation','set_orientation',8),('SetPosition','set_position',5),('SetRolloffFactor','set_rolloff',3),('SetVelocity','set_velocity',5),('CommitDeferredSettings','commit',1)]]
def prepare(out):
 bindings={'DirectSoundCreate':dict(helper='tribes_dsound_create',arguments=3,returns=True,guest_base=True),'DirectSoundEnumerateA':dict(helper='tribes_dsound_enumerate',arguments=2,returns=True,guest_base=False,cpu_argument=True)}
 rows=[('DirectSoundCreate',0xffd00000),('DirectSoundEnumerateA',0xffd00010)];stops=[]
 for i,(name,helper,n) in enumerate(METHODS):
  symbol='DS_'+name;rows.append((symbol,0xffd01000+16*i))
  if helper:bindings[symbol]=dict(helper='tribes_ds_'+helper,arguments=n,returns=True,guest_base=True)
  else:stops.append('define hidden fastcc void @tbimp_%s(ptr %%cpu) { call void @tribes_ds_stop(ptr %%cpu, i32 %d)\n unreachable\n}'%(symbol,i))
 for i,(name,helper,n) in enumerate(BUFFER_METHODS):
  symbol='DSB_'+name;rows.append((symbol,0xffd02000+16*i))
  if helper:bindings[symbol]=dict(helper='tribes_dsb_'+helper,arguments=n,returns=True,guest_base=True)
  else:stops.append('define hidden fastcc void @tbimp_%s(ptr %%cpu) { call void @tribes_ds_stop(ptr %%cpu, i32 %d)\n unreachable\n}'%(symbol,100+i))
 for i,(name,helper,n) in enumerate(LISTENER_METHODS):
  symbol='DSL_'+name;rows.append((symbol,0xffd03000+16*i));bindings[symbol]=dict(helper=helper,arguments=n,returns=True,guest_base=True)
 spec=importlib.util.spec_from_file_location('dsound_binding_generator',R/'scripts/gen-win32-bindings.py');gen=importlib.util.module_from_spec(spec);spec.loader.exec_module(gen)
 wrapper=out/'dsound-bindings.ll';wrapper.write_text(gen.generate(bindings,False)+'\ndeclare void @tribes_ds_stop(ptr, i32) noreturn\n'+'\n'.join(stops)+'\n')
 table='/* Finite routes generated by dsound_backend_inputs.py. */\n'+''.join('extern void tbimp_%s(void);\n'%name for name,_ in rows)
 table+='static const SoundExport sound_exports[]={\n'+''.join(' {"%s",0x%xu,(void *)tbimp_%s},\n'%(name,address,name) for name,address in rows)+'};\n'
 (out/'dsound-exports.inc').write_text(table)
 return [R/'port/core/guest_dsound.c',wrapper],bindings
